	_draw_text_left("CATSWEEPER", Vector2(181.0, 84.0), 43, CREAM)
	_draw_text_left("quiet logic for clever paws", Vector2(184.0, 127.0), 28, _with_alpha(CREAM, 0.82))

	var level_rect := Rect2(681.0, 54.0, 154.0, 68.0)
