	var mascot_duration := celebration_duration * 0.42
	var mascot_phase := clampf((win_time - mascot_delay) / maxf(mascot_duration, 0.001), 0.0, 1.0)
	var mascot_scale := lerpf(0.68, 1.0, _cartoon_settle(mascot_phase))
