func _cell_center(cell: int) -> Vector2:
	var slot := BOARD_RECT.size.x / float(grid_size)
	var row := cell / grid_size
	var column := cell % grid_size
	return BOARD_RECT.position + Vector2((float(column) + 0.5) * slot, (float(row) + 0.5) * slot)


